 "content": "def transform(grid):
    """Complete a horizontally shifted, incomplete copy of a row-band pattern.

    A repeated motif band acts as the reference; in a later aligned band,
    missing cells of the one-column-shifted pattern are marked with 1.
    """
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Split non-background content into horizontal bands.
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        bands.append((start, r))

    best = None
    for si, (s0, s1) in enumerate(bands):
        sh = s1 - s0
        if sh < 2:
            continue
        for ti, (t0, t1) in enumerate(bands):
            if ti <= si or t1 - t0 != sh:
                continue
            for dx in range(-3, 4):
                total = matches = missing = 0
                valid = True
                for dr in range(sh):
                    expected = {c + dx for c, v in enumerate(grid[s0+dr]) if v != bg and 0 <= c + dx < w}
                    actual = {c for c, v in enumerate(grid[t0+dr]) if v != bg}
                    if not expected or not actual:
                        valid = False
                        break
                    matches += len(expected & actual)
                    total += len(actual)
                    missing += len(expected - actual)
                if not valid or total == 0 or missing == 0:
                    continue
                score = matches / total
                # Require strong containment: target is the same motif shifted,
                # with at most small extra foreground noise.
                if score < 0.88:
                    continue
                candidate = (score, missing, s0, t0, sh, dx)
                if best is None or candidate[:2] > best[:2]:
                    best = candidate

    if best is not None:
        _, _, s0, t0, sh, dx = best
        for dr in range(sh):
            for c, v in enumerate(grid[s0+dr]):
                tc = c + dx
                if v != bg and 0 <= tc < w and grid[t0+dr][tc] == bg:
                    out[t0+dr][tc] = 1
    return out

if __name__ == '__main__':
