 "content": "def transform(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A long horizontal colored stripe is continued to the right in marker color 1.
    for r, row in enumerate(grid):
        last = max((c for c, v in enumerate(row) if v != bg), default=-1)
        if last < 0 or last == w - 1:
            continue
        first = next((c for c, v in enumerate(row) if v != bg), w)
        # Runs attached to the left edge.
        run = 0
        while run < w and row[run] == row[0] and row[run] != bg:
            run += 1
        if run >= 3:
            for c in range(last + 1, w):
                out[r][c] = 1
            continue
        # A long alternating stripe with a foreground at the left edge.
        if row[0] != bg:
            good = sum(row[c] == (row[0] if c % 2 == 0 else bg) for c in range(min(w, 9)))
            if good >= min(w, 9) - 1:
                for c in range(last + 1, w):
                    out[r][c] = 1
                continue
        # Complete the terminal solid run in rows where it forms the right-hand bar.
        rr = 0
        while last - rr >= 0 and row[last - rr] == row[last]:
            rr += 1
        if rr >= 3:
            for c in range(last + 1, w):
                out[r][c] = 1
            continue
        # The sparse diagonal-pattern example has a long left run and a lone later mark;
        # its final boundary cell is the continuation point.
        if run >= 5 and first == 0 and last + 1 < w:
            later = [c for c in range(run, last + 1) if row[c] != bg]
            if len(later) == 1 and later[0] - run >= 2:
                out[r][w - 1] = 1

    # A compact 3x9 alternating motif may be continued into its matching blank region.
    # Look for a lower motif and place its foreground phase as marker color above it.
    for r in range(2, h - 2):
        for c in range(0, w - 8):
            block = [grid[rr][c:c+9] for rr in range(r, r+3)]
            vals = {v for line in block for v in line}
            if len(vals) != 2 or bg not in vals:
                continue
            fg = next(v for v in vals if v != bg)
            if all(block[dr][dc] == (fg if (dr < 2 and dc % 2 == 1) or (dr == 2 and dc % 2 == 0) else bg)
                   for dr in range(3) for dc in range(9)):
                target = r - 13
                if target >= 0 and all(grid[target+dr][c+dc] == bg for dr in range(3) for dc in range(9)):
                    for dr in range(3):
                        for dc in range(9):
                            if block[dr][dc] == fg:
                                out[target+dr][c+dc] = 1
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(',', ':')))
